ALIVE = 'alive'
SILENT = 'silent'
UNREACHABLE = 'unreachable'
_MAX_HOST = 100
_MAX_PATH = 200
_MAX_MARKER = 200
_MAX_NAME = 40

def valid_host(host: str) -> bool:
    h = (host or '').strip().lower()
    if not h or len(h) > _MAX_HOST or h.startswith('.') or h.endswith('.') or ('..' in h):
        return False
    for ch in h:
        if not ('0' <= ch <= '9' or 'a' <= ch <= 'z' or ch in '-.'):
            return False
    return '.' in h

def valid_path(path: str) -> bool:
    p = (path or '').strip()
    if not p.startswith('/') or len(p) > _MAX_PATH:
        return False
    if '..' in p or '://' in p or '?' in p or ('#' in p) or ('//' in p):
        return False
    return True

def valid_name(name: str) -> bool:
    n = (name or '').strip().lower()
    if not n or len(n) > _MAX_NAME:
        return False
    for ch in n:
        if not ('0' <= ch <= '9' or 'a' <= ch <= 'z' or ch in '-_'):
            return False
    return True

def valid_marker(marker: str) -> bool:
    m = (marker or '').strip()
    if not m or len(m) > _MAX_MARKER:
        return False
    return '\n' not in m and '\r' not in m

def marker_present(body: str, marker: str) -> bool:
    if not marker:
        return False
    return marker.strip() in (body or '')

def url_for(host: str, path: str) -> str:
    return 'https://' + host.strip().lower() + path.strip()

def days_between(earlier_seconds, later_seconds):
    if earlier_seconds is None or later_seconds is None:
        return None
    if later_seconds < earlier_seconds:
        return 0
    return (later_seconds - earlier_seconds) // 86400

def epoch_seconds(stamp: str):
    s = (stamp or '').strip()
    if len(s) < 19 or s[4] != '-' or s[7] != '-' or (s[10] != 'T') or (s[13] != ':') or (s[16] != ':'):
        return None
    for i in (0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15, 17, 18):
        if not '0' <= s[i] <= '9':
            return None
    year, month, day = (int(s[0:4]), int(s[5:7]), int(s[8:10]))
    hour, minute, second = (int(s[11:13]), int(s[14:16]), int(s[17:19]))
    if not 1 <= month <= 12 or day < 1 or day > _days_in_month(year, month):
        return None
    if hour > 23 or minute > 59 or second > 60:
        return None
    return _days_from_civil(year, month, day) * 86400 + hour * 3600 + minute * 60 + second

def _days_in_month(year: int, month: int) -> int:
    if month == 2:
        leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
        return 29 if leap else 28
    return 30 if month in (4, 6, 9, 11) else 31

def _days_from_civil(year: int, month: int, day: int) -> int:
    y = year - (1 if month <= 2 else 0)
    era = (y if y >= 0 else y - 399) // 400
    year_of_era = y - era * 400
    day_of_year = (153 * (month + (-3 if month > 2 else 9)) + 2) // 5 + day - 1
    day_of_era = year_of_era * 365 + year_of_era // 4 - year_of_era // 100 + day_of_year
    return era * 146097 + day_of_era - 719468
from dataclasses import dataclass
import genlayer as gl
from genlayer.types import *
STATE_OPEN = 'open'
STATE_HALTED = 'halted'
STATE_RIPE = 'ripe'
GRACE_DAYS = 14

@gl.storage.allow
@dataclass
class Probate:
    opener: Address
    will: Address
    will_id: str
    owner: Address
    successor: Address
    pulse: Address
    pulse_id: str
    silence_days: u256
    last_alive_at_open: str
    opened_at: str
    halted: bool
    halted_at: str
    reason: str

class ProbateContract(gl.contract.Contract):
    will: Address
    cases: gl.storage.TreeMap[str, Probate]
    case_ids: gl.storage.DynArray[str]

    def __init__(self, will: str):
        self.will = _address(will)

    @gl.public.write
    def open(self, will_id: str) -> dict:
        at = self.will
        key = will_id.strip().lower()
        terms = gl.contract.get_at(at).view().get_will(key)
        if str(terms['state']) != 'held':
            raise gl.vm.UserError('that will is ' + str(terms['state']))
        successor = _address(terms['successor'])
        if successor.as_hex.lower() != gl.message.sender_address.as_hex.lower():
            raise gl.vm.UserError('only the named successor may open probate')
        pulse_at = _address(terms['pulse'])
        pulse_id = str(terms['pulse_id'])
        record = gl.contract.get_at(pulse_at).view().get_pulse(pulse_id)
        silent = int(str(record['silent_days']))
        wanted = int(str(terms['silence_days']))
        if silent < 0:
            raise gl.vm.UserError('how long the owner has been silent cannot be worked out')
        if silent < wanted:
            raise gl.vm.UserError(f'the owner has been silent {silent} days of the {wanted} required')
        case_id = at.as_hex.lower() + '|' + key
        if case_id in self.cases and (not self.cases[case_id].halted):
            raise gl.vm.UserError('probate is already open on that will')
        first_time = case_id not in self.cases
        self.cases[case_id] = Probate(opener=gl.message.sender_address, will=at, will_id=key, owner=_address(terms['owner']), successor=successor, pulse=pulse_at, pulse_id=pulse_id, silence_days=wanted, last_alive_at_open=str(record['last_alive']), opened_at=_stamp(), halted=False, halted_at='', reason=f'grace of {GRACE_DAYS} days is running; one signed transaction from the owner ends it')
        if first_time:
            self.case_ids.append(case_id)
        return _as_dict(case_id, self.cases[case_id], _now())

    @gl.public.write
    def halt(self, case_id: str) -> dict:
        key = case_id.strip().lower()
        case = self._get(key)
        if case.halted:
            raise gl.vm.UserError('that probate is already halted')
        record = gl.contract.get_at(case.pulse).view().get_pulse(case.pulse_id)
        seen = epoch_seconds(str(record['last_alive']))
        opened = epoch_seconds(case.opened_at)
        if seen is None or opened is None:
            raise gl.vm.UserError('a timestamp on this probate or pulse could not be read')
        if seen <= opened:
            raise gl.vm.UserError('the owner has not been seen since probate opened')
        case.halted = True
        case.halted_at = _stamp()
        case.reason = 'the owner answered during the grace period'
        self.cases[key] = case
        return _as_dict(key, case, _now())

    @gl.public.view
    def verdict(self, case_id: str) -> dict:
        key = case_id.strip().lower()
        if key not in self.cases:
            raise gl.vm.UserError('no such probate: ' + key)
        return _as_dict(key, self.cases[key], _now())

    @gl.public.view
    def settings(self) -> dict:
        return {'will': self.will.as_hex, 'grace_days': str(GRACE_DAYS)}

    @gl.public.view
    def case_list(self) -> list:
        return [c for c in self.case_ids]

    @gl.public.view
    def terms(self) -> dict:
        return {'grace_days': str(GRACE_DAYS)}

    def _get(self, key: str) -> Probate:
        if key not in self.cases:
            raise gl.vm.UserError('no such probate: ' + key)
        return self.cases[key]

def _stamp() -> str:
    return str(gl.message.raw['datetime'])

def _now():
    return epoch_seconds(_stamp())

def _address(value) -> Address:
    if hasattr(value, 'as_hex'):
        return value
    return Address(str(value).strip())

def _as_dict(key: str, case: Probate, now) -> dict:
    waited = days_between(epoch_seconds(case.opened_at), now)
    if case.halted:
        state = STATE_HALTED
    elif waited is not None and waited >= GRACE_DAYS:
        state = STATE_RIPE
    else:
        state = STATE_OPEN
    return {'case_id': key, 'state': state, 'opener': case.opener.as_hex, 'will': case.will.as_hex, 'will_id': case.will_id, 'owner': case.owner.as_hex, 'successor': case.successor.as_hex, 'pulse': case.pulse.as_hex, 'pulse_id': case.pulse_id, 'silence_days': str(case.silence_days), 'last_alive_at_open': case.last_alive_at_open, 'opened_at': case.opened_at, 'halted': case.halted, 'halted_at': case.halted_at, 'grace_days': str(GRACE_DAYS), 'waited_days': str(waited if waited is not None else -1), 'reason': case.reason}
